"""Prerequisites are available on the same lesson screen, including first use."""
DEFINITIONS = {
 'example': ('Объект и обучающий пример', 'Объект — то, о чём принимают решение. Обучающий пример содержит доступное описание объекта и, когда требуется, правильный ответ. Число строк не всегда равно числу независимых объектов.', 'Три снимка одного дерева — три строки, но один источник наблюдения.'),
 'model': ('Модель', 'Модель — правило вычисления выхода по входу. В машинном обучении часть этого правила задают параметры, подбираемые на данных. Выход может быть числом, классом или последовательностью.', 'Правило y = w*x + b превращает число x в прогноз y; w и b — параметры.'),
 'features': ('Признаки', 'Признаки — сведения, передаваемые модели при прогнозе. Они должны существовать в момент решения; ответ из будущего нельзя включать во вход.', 'Температура утром доступна для утреннего прогноза; результат вечернего ремонта — нет.'),
 'target': ('Цель предсказания', 'Target — величина или метка, которую модель должна предсказать. Во время обучения с учителем её используют для сравнения с прогнозом; при обычном применении она ещё неизвестна.', 'Для оценки цены target — действительная цена, вход — характеристики объекта.'),
 'loss': ('Функция потерь', 'Loss переводит несовпадение прогноза и обучающего ответа в число. Оптимизация пытается уменьшить выбранную потерю. Показатель полезности на практике может отличаться от этой функции.', 'Для прогноза 5 и ответа 3 квадрат ошибки равен (5−3)² = 4.'),
 'parameters': ('Параметры модели', 'Параметры — внутренние числа модели, которые меняются при обучении. Их отличают от гиперпараметров, задающих процедуру обучения.', 'В y = w*x + b числа w и b обучаются, а число эпох задаёт разработчик.'),
 'split': ('Train, validation и test', 'Train используют для подбора параметров. Validation — для выбора вариантов и настроек. Test — для окончательной независимой оценки после выбора. Общие источники и временной порядок учитывают при разделении.', 'Настроить порог по validation допустимо; многократно выбирать порог по test — значит использовать test для настройки.'),
 'metrics': ('Метрика', 'Метрика — явно заданный способ измерить качество на наборе случаев. Нужно указать знаменатель, направление улучшения и поведение при неопределённом результате.', 'Recall измеряет найденные положительные случаи среди всех настоящих положительных.'),
 'confusion': ('Таблица исходов классификации', 'Положительный класс обозначим 1. TP: модель сказала 1 и истина 1. FP: сказала 1, истина 0. FN: сказала 0, истина 1. TN: сказала 0 и истина 0. Слова true/false оценивают правильность, positive/negative — решение модели.', 'Сигнал тревоги на безопасном событии — FP, а пропущенная настоящая опасность — FN.'),
 'precision_recall': ('Precision и recall', 'Precision = TP/(TP+FP): доля настоящих положительных среди положительных решений. Recall = TP/(TP+FN): доля найденных среди настоящих положительных. При нулевом знаменателе нужно заранее оговорить соглашение.', 'При TP=3, FP=1, FN=2 precision=3/4, recall=3/5.'),
 'probability': ('Вероятность и условие', 'Вероятность — число от 0 до 1 для события в заданных условиях. Условная вероятность P(A|B) относится только к случаям, где произошло B; P(A|B) обычно не равна P(B|A). Частота на наблюдениях оценивает вероятность с неопределённостью.', 'Если из 10 тревог 7 верны, частота опасности среди тревог 0.7; это не доля всех опасностей, которые нашли.'),
 'threshold': ('Порог решения', 'Score — численная оценка. Порог превращает её в решение: в наших задачах положительное решение получается при score >= threshold. Изменение порога не является переобучением весов модели.', 'При score=0.6 порог 0.5 даёт 1, порог 0.7 даёт 0.'),
 'vector': ('Вектор и норма', 'Вектор — упорядоченный набор чисел. Координаты имеют определённый смысл; перестановка координат меняет объект. Евклидова норма sqrt(sum(x_i²)) измеряет длину в выбранных единицах.', 'Вектор (3,4) имеет норму 5; расстояние до (0,0) тоже 5.'),
 'matrix': ('Матрица и форма', 'Матрица — прямоугольная таблица чисел с формой строки × столбцы. Умножение (n×r) на (r×m) даёт (n×m); элемент результата — сумма произведений соответствующей строки и столбца. Это не поэлементное умножение.', 'Строка [2,3] и столбец [4,5] дают скаляр 2*4 + 3*5 = 23.'),
 'scaling': ('Масштабирование признаков', 'Масштабирование меняет единицы признаков. Стандартизация вычитает среднее и делит на стандартное отклонение; эти величины оценивают только на train. Оно важно там, где используется расстояние или размер коэффициентов.', 'Признак в миллиметрах численно в тысячу раз больше того же признака в метрах.'),
 'fit_transform': ('Обучить и применить преобразование', 'fit оценивает параметры преобразования по данным; transform применяет уже найденное правило. fit_transform объединяет эти действия на обучающей части. На проверочной части параметры не переоценивают.', 'Среднее train равно 4: пропуск и в train, и в test заменяют 4.'),
 'hyperparameter': ('Гиперпараметр', 'Гиперпараметр задаёт способ обучения или устройство модели. Его выбирают по validation либо cross-validation внутри обучающей части, затем отдельно проверяют итог.', 'Глубина дерева и коэффициент регуляризации — настройки; найденные по данным пороги дерева — параметры.'),
 'tree': ('Дерево решений', 'Дерево последовательно проверяет признаки и ведёт объект к листу с прогнозом. Слишком глубокое дерево может запомнить частные особенности train. Ограничение глубины меняет допустимую сложность.', 'Вопрос «температура > 20?» разбивает записи на две ветви; дальше в каждой может быть следующий вопрос.'),
 'derivative': ('Производная', 'Производная показывает локальную скорость изменения функции по одному числу. Частная производная меняет одну координату, удерживая остальные фиксированными. Это локальное описание, а не обещание на произвольно большом шаге.', 'У f(w)=w² производная 2w; при w=3 локальный наклон равен 6.'),
 'gradient': ('Градиент', 'Градиент — вектор частных производных потери по параметрам. Для достаточно малого шага движение против градиента уменьшает гладкую функцию локально; размер шага задаёт learning rate.', 'Обновление w_new = w − learning_rate * gradient отделяет направление от длины шага.'),
 'batch': ('Batch', 'Batch — набор примеров, обрабатываемых совместно. Размер batch — число примеров; длина одного примера и число признаков являются другими измерениями.', 'Массив формы [8,20] может хранить 8 примеров по 20 признаков.'),
 'softmax': ('Логиты и softmax', 'Логиты — произвольные численные оценки классов. Softmax вычисляет exp(z_i)/sum(exp(z_j)), получая неотрицательные веса с суммой 1. Общий сдвиг всех логитов не меняет результат.', 'Для двух одинаковых логитов softmax даёт [0.5,0.5].'),
 'sequence': ('Последовательность', 'Последовательность хранит элементы в определённом порядке. Индекс обозначает позицию, а не значение элемента. Две последовательности с одинаковыми элементами в разном порядке могут иметь разный смысл.', 'В [A,B,A] позиции 0 и 2 различны, хотя значения совпадают.'),
 'tokens': ('Токен', 'Токен — единица представления текста, которой токенизатор назначает ID. Это может быть слово, часть слова, знак или специальный символ. Число токенов не равно числу слов.', 'Редкое слово может разбиться на несколько токенов; контекстный лимит считают в токенах.'),
 'attention': ('Attention', 'Attention вычисляет веса для доступных элементов и складывает их представления с этими весами. Query сопоставляется с keys, затем веса применяются к values. Маска ограничивает допустимые связи.', 'Вес 0.8 у одного фрагмента означает сильный вклад в вычисление, но не доказывает его достоверность.'),
 'sft': ('Supervised fine-tuning', 'SFT — дообучение модели на примерах желаемого ответа. В языковой модели вход и ответ оформляют согласно её шаблону, а потерю считают на выбранных токенах.', 'Пары «запрос → качественный ответ» учат образцу поведения, но не обеспечивают актуальность всех фактов.'),
 'evidence': ('Подтверждающие данные', 'Основание поддерживает конкретное утверждение и имеет проверяемое происхождение. Похожесть текста, уверенный тон и количество повторов не заменяют независимую проверку.', 'Для утверждения о действующем правиле нужен документ нужного объекта и версии.'),
 'schema': ('Схема данных', 'Схема описывает допустимые ключи, типы, обязательные поля и иногда ограничения значений. Проверка формы не доказывает истинность содержания и не выдаёт разрешение на действие.', 'Строка path и целое limit могут соответствовать схеме, но пользователь всё ещё не разрешал удаление файла.'),
 'tool': ('Инструмент агента', 'Инструмент — внешняя операция с именем, аргументами и результатом либо ошибкой. Модель предлагает вызов, а приложение проверяет и исполняет его. Текст «готово» не равен выполненной операции.', 'read_status(device_id) возвращает состояние; утверждение модели должно опираться на этот результат.'),
 'state': ('Состояние', 'Состояние — данные, которые сохраняются между шагами процесса или вызовами объекта. Переход меняет состояние согласно правилу. Инвариант — свойство, которое должно сохраняться после каждого допустимого перехода.', 'У счётчика состояние total; после добавления x новый total равен прежнему total+x.'),
 'retrieval': ('Поиск документов', 'Retrieval выбирает кандидатов из хранилища для запроса. Поиск и генерация ответа — разные стадии. Нужный документ может не попасть в кандидаты; тогда генератор не сможет честно сослаться на него.', 'Сначала выбирают 10 фрагментов, затем сравнивают и используют несколько подходящих.'),
 'cache': ('Кэш', 'Кэш сохраняет результат вычисления для повторного использования по ключу. Корректность зависит от ключа, условий применимости и удаления устаревших записей. Попадание в кэш не является проверкой истины.', 'Смена версии документа должна менять ключ или делать прежний ответ недействительным.'),
 'quantization_intro': ('Квантизация', 'Квантизация представляет числа ограниченным набором значений, обычно меньшим числом бит. Это снижает память при поддержке формата, но вносит ошибку и требует отдельной оценки качества и скорости.', 'В простой схеме q=round(x/scale), восстановление x_hat=q*scale; это приближение.'),
 'preferences': ('Предпочтения', 'Предпочтение сравнивает допустимые варианты по желательности в конкретном контексте. Наблюдаемые оценки людей могут быть неполными, шумными и противоречивыми.', 'Предпочтение краткости не означает согласие на ответ без необходимого обоснования.'),
 'authorization': ('Разрешение на действие', 'Авторизация проверяет, имеет ли конкретный субъект право выполнить конкретное действие над конкретным объектом. Проверка аргументов и высокая полезность не заменяют разрешения.', 'Разрешение читать один файл не даёт права отправлять его содержимое третьей стороне.'),
 'baseline': ('Базовый вариант', 'Baseline — явно описанный вариант для сравнения. Сравнение должно использовать одинаковую задачу, данные и бюджет, иначе причина изменения результата неясна.', 'Один и тот же тест выполняют с исходным поиском и с новым reranker.'),
 'budget': ('Бюджет выполнения', 'Бюджет ограничивает число шагов, время, стоимость или память. Это разные единицы; ограничение проверяют до расхода и после полученного результата.', 'Если осталось 2 разрешённых вызова, план из 3 вызовов не помещается в бюджет.'),
 'latency': ('Задержка', 'Latency — время между определённым началом и концом операции. Нужно назвать границы измерения; время до первого токена отличается от времени до полного ответа.', 'Ответ может начаться через 0.2 секунды и завершиться через 8 секунд.'),
 'privacy': ('Минимизация данных', 'В журнал сохраняют только данные, необходимые для конкретной проверки, с подходящим доступом и сроком хранения. Секреты и персональные поля по возможности удаляют или маскируют до записи.', 'Для измерения задержки нужен timestamp, но обычно не нужен полный секретный текст пользователя.'),
 'rubric': ('Рубрика оценки', 'Рубрика задаёт критерии, шкалу и признаки каждого балла. Разные критерии следует оценивать отдельно; один общий балл может скрыть важную ошибку.', 'Полнота, подтверждённость и отсутствие запрещённого действия — три различных критерия.'),
 'regularization': ('Регуляризация', 'Регуляризация ограничивает допустимую сложность или предпочтение решений, чтобы уменьшить подгонку к случайным особенностям train. Коэффициент регуляризации выбирают по независимой от обучения проверке.', 'Штраф L2 увеличивает целевую функцию при больших квадратов коэффициентов.'),
 'leakage': ('Утечка данных', 'Утечка появляется, когда в обучении или выборе решения используется информация, недоступная в настоящем сценарии оценки. Она может скрываться в признаках, общих группах или многократном выборе по test.', 'Нормализация, обученная на всём датасете до split, уже использовала проверочную часть.'),
}

def prerequisites(keys):
    return [dict(name=DEFINITIONS[k][0], explanation=DEFINITIONS[k][1], example=DEFINITIONS[k][2]) for k in keys]
